Nm_y = (nx+1)*ny*(nz+1)             # mid-side nodes on y-edges
Nm_z = (nx+1)*(ny+1)*nz             # mid-side nodes on z-edges

dx, dy, dz = L/nx, H/ny, T/nz

# Global node ID helpers (sequential)
def cid(i, j, k):
    return 1 + i + (nx+1)*j + (nx+1)*(ny+1)*k

def mx(ex, j, k):
    return Nc + 1 + ex + nx*j + nx*(ny+1)*k

def my(i, ey, k):
    return Nc + Nm_x + 1 + i + (nx+1)*ey + (nx+1)*ny*k

